/**
 * Pure core of the Docker network facts (U3.2): which compose networks are empty, and may
 * therefore be regenerated by `compose up` (autonomous-cleanup design §4 U3 "Garbage", C8).
 *
 * No I/O. Emptiness is counted from the containers' own `NetworkSettings` (running AND stopped),
 * never from `docker network inspect`'s `Containers` map, which omits stopped containers. A
 * network any stack declares `external` is never released, and when a stack's declarations could
 * not be read at all, nothing is released: a missing fact never becomes a deletion.
 */

import { COMPOSE_PROJECT_LABEL, type InspectedContainer } from './containers-core'

/** A docker network as `docker network inspect` reports it, reduced to what the core reads. */
export interface DockerNetworkFact {
  id: string
  name: string
  driver: string
  /** Value of the `com.docker.compose.project` label, or null for a hand-made network. */
  project: string | null
  /** IPv4 subnets (CIDR). IPv6 is not part of the bridge-pool accounting. */
  subnets: string[]
}

/** What the machine's compose stacks declare, handed in by the shell. */
export interface ExternalDeclarations {
  /** Resolved names of every network some stack declares `external`. */
  names: ReadonlySet<string>
  /** Compose projects whose declarations could not be read (their config failed to resolve). */
  unresolvedProjects: readonly string[]
}

export type HeldReason = 'external' | 'externals-unresolved'

export interface EmptyNetworkPlan {
  /** Empty compose networks that nothing declares external: safe for `compose up` to recreate. */
  garbage: DockerNetworkFact[]
  /** Empty compose networks that must stay, and why. */
  held: { network: DockerNetworkFact; reason: HeldReason }[]
}

const BUILT_IN_NETWORKS = new Set(['bridge', 'host', 'none'])

function asRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null
}

function asString(v: unknown): string {
  return typeof v === 'string' ? v : ''
}

const IPV4_CIDR = /^\d{1,3}(\.\d{1,3}){3}\/\d{1,2}$/

/** Parses `docker network inspect <ids…>` (a JSON array). Malformed input yields `[]`. */
export function parseNetworkInspect(stdout: string): DockerNetworkFact[] {
  let parsed: unknown
  try {
    parsed = JSON.parse(stdout)
  } catch {
    return []
  }
  if (!Array.isArray(parsed)) return []
  const out: DockerNetworkFact[] = []
  for (const raw of parsed) {
    const n = asRecord(raw)
    const id = asString(n?.Id)
    const name = asString(n?.Name)
    if (!n || !id || !name) continue
    const config = asRecord(n.IPAM)?.Config
    const subnets: string[] = []
    if (Array.isArray(config)) {
      for (const entry of config) {
        const subnet = asString(asRecord(entry)?.Subnet)
        if (IPV4_CIDR.test(subnet)) subnets.push(subnet)
      }
    }
    out.push({
      id,
      name,
      driver: asString(n.Driver),
      project: asString(asRecord(n.Labels)?.[COMPOSE_PROJECT_LABEL]) || null,
      subnets
    })
  }
  return out
}

/**
 * The docker network names one project declares `external`, from `docker compose config
 * --format json`. Compose resolves an external network's `name` (falling back to the key). Null
 * when the output is not a config object or a name still holds an unresolved `${…}`: the caller
 * must then treat the project as unresolved, never as "declares nothing".
 */
export function externalNetworkNamesOf(configJson: string): string[] | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(configJson)
  } catch {
    return null
  }
  const cfg = asRecord(parsed)
  if (!cfg) return null
  const networks = asRecord(cfg.networks)
  if (!networks) return []
  const names: string[] = []
  for (const [key, raw] of Object.entries(networks)) {
    const entry = asRecord(raw)
    if (!entry) continue
    const external = entry.external
    if (external !== true && !asRecord(external)) continue
    const name = asString(asRecord(external)?.name) || asString(entry.name) || key
    if (name.includes('$')) return null
    names.push(name)
  }
  return names
}

function compareByName(a: DockerNetworkFact, b: DockerNetworkFact): number {
  return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
}

/**
 * C8: every network carrying a compose project label with zero containers attached (running or
 * stopped), minus the ones any stack declares `external`. While any project's declarations are
 * unresolved nothing is released (`held`, `externals-unresolved`).
 */
export function planEmptyComposeNetworks(input: {
  networks: readonly DockerNetworkFact[]
  containers: readonly InspectedContainer[]
  externals: ExternalDeclarations
}): EmptyNetworkPlan {
  const attachedNames = new Set<string>()
  const attachedIds = new Set<string>()
  for (const c of input.containers) {
    for (const a of c.networks) {
      attachedNames.add(a.name)
      if (a.id) attachedIds.add(a.id)
    }
  }

  const garbage: DockerNetworkFact[] = []
  const held: EmptyNetworkPlan['held'] = []
  for (const network of [...input.networks].sort(compareByName)) {
    if (!network.project || BUILT_IN_NETWORKS.has(network.name)) continue
    if (attachedNames.has(network.name) || attachedIds.has(network.id)) continue
    if (input.externals.names.has(network.name)) {
      held.push({ network, reason: 'external' })
    } else if (input.externals.unresolvedProjects.length > 0) {
      held.push({ network, reason: 'externals-unresolved' })
    } else {
      garbage.push(network)
    }
  }
  return { garbage, held }
}
